//! `ColorConverter::rgbToCMYK` — reverse-engineered from black-box differential
//! testing of /workspace/dataset/test12_executable (164,303 oracle invocations,
//! 0 mismatches; 93,356 distinct CMYK output tuples).
//!
//! Confirmed C++ source shape:
//! ```cpp
//! float max = std::max(std::max(r, g), b);
//! float k = 1.0f - max;
//! if (k == 1) { c = m = y = 0; }          // NOT `max == 0`, NOT `k >= 1`
//! else {
//!     c = (1.0f - r - k) / (1.0f - k);    // i.e. ((1-r)-k) / (1-k)
//!     m = (1.0f - g - k) / (1.0f - k);
//!     y = (1.0f - b - k) / (1.0f - k);
//! }
//! ```
//! All arithmetic is IEEE-754 binary32, round-to-nearest-even, left-to-right,
//! no contraction, no double/extended intermediates.

/// CMYK result. Fields are raw `f32`; no clamping is performed anywhere, so
/// out-of-gamut inputs yield out-of-range / infinite / NaN components.
#[derive(Debug, Clone, Copy, PartialEq)]
pub struct Cmyk {
    pub c: f32,
    pub m: f32,
    pub y: f32,
    pub k: f32,
}

/// Exactly `std::max(a, b)` from libstdc++: `(a < b) ? b : a`.
///
/// Returns the FIRST argument on ties (so `max(-0.0, 0.0) == -0.0`) and returns
/// the first argument whenever either operand is NaN (all `<` comparisons are
/// false). Evidence: `(-nan, 0.5, 0.5)` -> cmyk `-nan -nan -nan -nan` (max is
/// the NaN, so k is NaN), whereas `(0.5, nan, 0.5)` -> cmyk `0 nan 0 0.5`
/// (max = 0.5, the NaN loses the reduction and only leaks into `m`).
#[inline]
fn std_max(a: f32, b: f32) -> f32 {
    if a < b { b } else { a }
}

/// `max = std::max(std::max(r, g), b)` — the 3-way reduction used by the library.
#[inline]
fn max3(r: f32, g: f32, b: f32) -> f32 {
    std_max(std_max(r, g), b)
}

/// Convert linear RGB components to CMYK, bit-exactly reproducing the C++ oracle.
///
/// # Pinned details and the inputs that pin them
///
/// * `k = 1.0f32 - max`. A `1 - max` int literal, and a `double` intermediate
///   rounded back to `f32`, are *bitwise identical* for all 2^32 float values of
///   `max` (verified exhaustively), so the choice is unobservable.
///
/// * The guard is `k == 1.0`, **not** `max == 0.0`:
///   `(1e-8, 0, 0)` -> `0 0 0 1`. Here `max = 1e-8 != 0`, but
///   `1.0f - 1e-8f` rounds to exactly `1.0f` (1e-8 < 2^-25), so the guard fires.
///   A `max == 0` guard would divide by `1 - k == 0` and print `-nan -nan -nan 1`.
///   `(2.98023224e-08, 0, 0)` -> `0 0 0 1` (just under 2^-25) vs
///   `(3.1e-8, 0, 0)` -> `0 1 1 1` (just over 2^-25, guard does not fire):
///   the guard boundary sits exactly at the `1.0f - max == 1.0f` rounding
///   threshold, not at `max == 0`.
///
/// * The guard is **not** `k >= 1`: `(-1, -1, -1)` -> `-0 -0 -0 2` and
///   `(-2.6932409e-07, -4.42285057e-07, -3.46639865e-07)` -> `-0 -1 -0.5 1`
///   both have `k > 1` yet still take the division branch.
///   `(k == 1)` and `((1.0 - k) == 0.0)` are provably equivalent for all 2^32
///   floats (verified exhaustively), so that spelling is unobservable.
///
/// * There is a guard at all: `(0, 0, 0)` -> `0 0 0 1`, not `-nan -nan -nan 1`.
///
/// * The guard writes literal `+0.0`, not a sign-carrying zero:
///   `(-1e-8, -1e-8, -1e-8)` -> `0 0 0 1` (prints `0`, not `-0`), even though
///   `max < 0` there.
///
/// * The denominator is `1.0f - k`, **not** `max` (they differ because `k` is
///   itself rounded): `(3.1e-8, 0, 0)` -> `0 1 1 1`, where `1 - k == 2^-24 ==
///   5.96e-8` while `max == 3.1e-8`; dividing by `max` would give `0 1.92273
///   1.92273 1`.
///
/// * The channel numerator is `((1 - x) - k)`, **not** `(1 - (x + k))`:
///   `(1e30, 1, 1)` -> `0 1 1 -1e+30`; the `(1 - (r + k))` grouping yields
///   `c = 1e-30`.
///
/// * It is `(1 - x - k) / (1 - k)`, **not** the algebraically identical
///   `(max - x) / max`: `(1e-7, 1e-8, 1e-9)` -> `0 1 1 1`, while
///   `(max - x) / max` yields `0 0.9 0.99 1`. Likewise not `((1-k) - x) / (1-k)`
///   (yields `0.161139 0.916114 0.991611 1`) and not `1 - x/max`
///   (`(inf, 0.2, 0.3)` -> `-nan -nan -nan -inf`, but `1 - x/max` gives
///   `-nan 1 1 -inf`).
///
/// * It is a true division, not a multiply by a precomputed reciprocal
///   `1.0f / (1.0f - k)`: `(0.970731616, 0.244352102, 0.794469595)` ->
///   `0 0.74828 0.181576 0.0292684`; the reciprocal form gives `m = 0.748281`.
///
/// * No `double` intermediates anywhere in the channels. Full-double evaluation
///   is killed by `(3.1e-8, 0, 0)` (gives `c = 0.479906` instead of `0`);
///   float-numerator-with-double-denominator is killed by
///   `(3.09588604e-19, 24461076, -1.63573056e+17)` -> oracle
///   `1 0 6.68708e+09 -2.44611e+07`, mixed form gives `y = 6.68707e+09`.
///
/// # Non-finite behaviour (all reproduced bit-exactly, incl. NaN sign bits)
///
/// | input                | cmyk output              |
/// |----------------------|--------------------------|
/// | `inf 0.2 0.3`        | `-nan -nan -nan -inf`    |
/// | `-inf 0.2 0.3`       | `inf 0.333333 0 0.7`     |
/// | `nan 0.2 0.3`        | `nan nan nan nan`        |
/// | `inf inf inf`        | `-nan -nan -nan -inf`    |
/// | `-inf -inf -inf`     | `-nan -nan -nan inf`     |
/// | `inf -inf 0.5`       | `-nan -nan -nan -inf`    |
/// | `-nan 0.5 0.5`       | `-nan -nan -nan -nan`    |
/// | `0.5 nan 0.5`        | `0 nan 0 0.5`            |
///
/// The `-nan` results come from `inf - inf` producing the x86 default QNaN
/// (sign bit set); `1.0 - nan` propagates the operand's NaN sign unchanged,
/// which is what native `f32` arithmetic on x86-64 does in Rust as well.
#[inline]
pub fn rgb_to_cmyk(r: f32, g: f32, b: f32) -> Cmyk {
    let max = max3(r, g, b);
    let k = 1.0f32 - max;

    if k == 1.0f32 {
        // Achromatic / black guard. `k` is exactly 1.0f32 here by construction,
        // so writing `k: 1.0` instead is indistinguishable.
        Cmyk { c: 0.0f32, m: 0.0f32, y: 0.0f32, k }
    } else {
        // A shared `den` is bit-identical to repeating `(1.0f - k)` three times.
        let den = 1.0f32 - k;
        Cmyk {
            c: (1.0f32 - r - k) / den,
            m: (1.0f32 - g - k) / den,
            y: (1.0f32 - b - k) / den,
            k,
        }
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    fn bits(v: [f32; 4]) -> [u32; 4] {
        [v[0].to_bits(), v[1].to_bits(), v[2].to_bits(), v[3].to_bits()]
    }

    #[test]
    fn guard_is_k_eq_one_not_max_eq_zero() {
        // (1e-8, 0, 0): max != 0 but 1.0f - max == 1.0f  ->  guard fires.
        let o = rgb_to_cmyk(1e-8, 0.0, 0.0);
        assert_eq!(bits([o.c, o.m, o.y, o.k]), bits([0.0, 0.0, 0.0, 1.0]));
        // Just past the 2^-25 threshold the guard must NOT fire.
        let o = rgb_to_cmyk(3.1e-8, 0.0, 0.0);
        assert_eq!(o.c, 0.0);
        assert_eq!(o.m, 1.0);
        assert_eq!(o.y, 1.0);
    }

    #[test]
    fn guard_writes_positive_zero() {
        // max < 0 yet the guard still fires and must emit +0.0, printing "0".
        let o = rgb_to_cmyk(-1e-8, -1e-8, -1e-8);
        assert_eq!(bits([o.c, o.m, o.y, o.k]), bits([0.0, 0.0, 0.0, 1.0]));
    }

    #[test]
    fn no_k_ge_one_guard() {
        // Oracle: -1 -1 -1  ->  "-0 -0 -0 2"
        let o = rgb_to_cmyk(-1.0, -1.0, -1.0);
        assert_eq!(o.k, 2.0);
        assert!(o.c == 0.0 && o.c.is_sign_negative());
        assert!(o.m == 0.0 && o.m.is_sign_negative());
        assert!(o.y == 0.0 && o.y.is_sign_negative());
    }

    #[test]
    fn not_max_minus_x_over_max() {
        // (max - x)/max would give 0 / 0.9 / 0.99; the real formula gives 0/1/1.
        let o = rgb_to_cmyk(1e-7, 1e-8, 1e-9);
        assert_eq!(o.c, 0.0);
        assert_eq!(o.m, 1.0);
        assert_eq!(o.y, 1.0);
    }

    #[test]
    fn not_one_minus_sum_grouping() {
        // (1 - (r + k)) would give c = 1e-30 here; correct answer is exactly 0.
        let o = rgb_to_cmyk(1e30, 1.0, 1.0);
        assert_eq!(o.c, 0.0);
        assert_eq!(o.k, -1e30);
    }

    #[test]
    fn default_case() {
        // Oracle default args 0.4 0.2 0.8  ->  "0.5 0.75 0 0.2"
        let o = rgb_to_cmyk(0.4, 0.2, 0.8);
        assert_eq!(o.c, 0.5);
        assert_eq!(o.m, 0.75);
        assert_eq!(o.y, 0.0);
        assert_eq!(o.k, 0.2f32);
    }

    #[test]
    fn nonfinite() {
        let o = rgb_to_cmyk(f32::INFINITY, 0.2, 0.3);
        assert!(o.c.is_nan() && o.c.is_sign_negative()); // prints "-nan"
        assert_eq!(o.k, f32::NEG_INFINITY);

        let o = rgb_to_cmyk(f32::NEG_INFINITY, 0.2, 0.3);
        assert_eq!(o.c, f32::INFINITY);
        assert_eq!(o.k, 0.7f32);
        assert_eq!(o.y, 0.0);

        // NaN loses the std::max reduction against 0.5, so only `m` is NaN.
        let o = rgb_to_cmyk(0.5, f32::NAN, 0.5);
        assert_eq!(o.c, 0.0);
        assert!(o.m.is_nan());
        assert_eq!(o.y, 0.0);
        assert_eq!(o.k, 0.5);
    }
}

//! HSV `s` and `v` extracted from `ColorConverter::rgbToHSV` by black-box
//! differential testing against `/workspace/dataset/test12_executable`
//! (144 254 oracle invocations, 0 mismatches).
//!
//! All arithmetic is IEEE-754 binary32 (`f32`).

/// `std::max(a, b)` == `(a < b) ? b : a` — returns the FIRST argument on ties,
/// and returns `a` whenever either operand is NaN (because `a < b` is false).
#[inline]
pub fn cpp_max(a: f32, b: f32) -> f32 {
    if a < b { b } else { a }
}

/// `std::min(a, b)` == `(b < a) ? b : a` — returns the FIRST argument on ties,
/// and returns `a` whenever either operand is NaN.
#[inline]
pub fn cpp_min(a: f32, b: f32) -> f32 {
    if b < a { b } else { a }
}

/// `std::max(std::max(r, g), b)`.
///
/// Tie/NaN behaviour pinned by:
/// * `(-0.0, 0.0, 0.0)` -> `hsv.v == -0` (prints `-0`), so `r` wins over the
///   numerically-equal `+0.0` of `g` and `b`.
/// * `(0.1, NaN, 0.3)` -> `hsv.v == 0.3`, `hsv.s == 0.666667`: the NaN is
///   *dropped* (`0.1 < NaN` is false -> keeps `0.1`, then `0.1 < 0.3` -> `0.3`),
///   i.e. `std::max`, not Rust's NaN-suppressing `f32::max` and not `fmaxf`.
#[inline]
pub fn max3(r: f32, g: f32, b: f32) -> f32 {
    cpp_max(cpp_max(r, g), b)
}

/// `std::min(std::min(r, g), b)`.
#[inline]
pub fn min3(r: f32, g: f32, b: f32) -> f32 {
    cpp_min(cpp_min(r, g), b)
}

/// `hsv.v`.
///
/// `v = max`, a verbatim copy of one of the input floats — no clamping, no
/// re-derivation.
///
/// Discriminating inputs:
/// * `(-1, -1, -1)` -> `hsv.v == -1`, refuting any `max(0, .)` clamp
///   (`(max < 0) ? 0 : max` would print `0`).
/// * `(0, -0.5, 1e-7)` -> `hsv.v == 1e-07`, refuting `v = min + delta`
///   (that reassociation prints `1.19209e-07`) and `v = (max+min)/2 + delta/2`
///   (prints `1.04308e-07`).
/// * `(0, 1, -inf)` -> `hsv.v == 1`, refuting `min + (max - min)`
///   (`-inf + inf` = `-nan`).
///
/// NOTE: whether the C++ struct field is `float` or `double` is **unobservable**.
/// `v` is an exact copy of an input binary32 and the widening `float -> double`
/// is exact, so both storage choices print identically under `%.6g` for every
/// possible input. `f32` is chosen for consistency with the rest of the library
/// (established via `yuv.v`).
#[inline]
pub fn hsv_v(r: f32, g: f32, b: f32) -> f32 {
    max3(r, g, b)
}

/// `hsv.s`.
///
/// ```text
/// float max   = std::max(std::max(r, g), b);
/// float min   = std::min(std::min(r, g), b);
/// float delta = max - min;
/// float s     = (max == 0.0f) ? 0.0f : (delta / max);
/// ```
///
/// The guard is an **IEEE `==` comparison against zero**, and the guarded value
/// is the literal `+0.0f`. Every alternative was actively refuted:
///
/// | candidate | killed by | oracle | candidate |
/// |---|---|---|---|
/// | `max <= 0 ? 0 : d/max`      | `(-1, -1, -2)`            | `-1`     | `0`      |
/// | `max > 0 ? d/max : 0`       | `(-1, -1, -1)`            | `-0`     | `0`      |
/// | `max == 0 ? delta : d/max`  | `(0, 0, -1)`              | `0`      | `1`      |
/// | `delta == 0 ? 0 : d/max`    | `(0, 0, -1)`              | `0`      | `inf`    |
/// | `max == min ? 0 : d/max`    | `(0, 0, -1)`              | `0`      | `inf`    |
/// | `max == 0 ? -0.0f : d/max`  | `(-0.0, -1, -2)`          | `0`      | `-0`     |
/// | no guard at all (`d/max`)   | `(0, 0, 0)`               | `0`      | `-nan`   |
/// | `1 - min/max`               | `(0, -0.0, inf)`          | `-nan`   | `1`      |
/// | `(max>0 \|\| max<0) ? d/max : 0` | `(NaN, 0, 0)`        | `nan`    | `0`      |
/// | `delta * (1.0f / max)`      | `(0.851135075, 2.41347075, 0.246790618)` | `0.897744` | `0.897745` |
/// | all-`f64` arithmetic        | `(-0.0731233805, -0.163357973, 1.05198824)` | `1.15529` | `1.15528` |
///
/// Key facts the table encodes:
/// * **`==` not `<=`**: `(-1, -1, -2)` has `max = -1 < 0`, `delta = 1`, and the
///   oracle prints `-1` = `1 / -1`. A `<= 0` guard would print `0`.
/// * **`-0.0` takes the guard**: `(-0.0, -1, -2)` has `max = -0.0` and
///   `delta = 2`; the oracle prints `0`. Ungated this would be `2 / -0.0 = -inf`.
///   Since `-0.0 == 0.0` is true in IEEE, a plain `==` reproduces this — no
///   bit-pattern / `signbit` test is involved.
/// * **the constant is `+0.0`, not `delta`**: same input, `delta = 2`, yet `s`
///   prints `0`. Also `(-0.0, -inf, 0)` has `delta = +inf` and still prints `0`.
/// * **the constant is `+0.0`, not `-0.0`**: `(-0.0, -1, -2)` prints `0`, not `-0`.
/// * **no epsilon guard**: `(1.17549435e-38, -3, -3)` prints `s = 2.55212e+38`,
///   so `max` merely being tiny does not trigger the guard.
/// * **NaN takes the division branch**: `max == 0.0` is false for NaN, so
///   `(NaN, 0, 0)` yields `NaN / NaN = nan`. A `(max > 0 || max < 0)` guard would
///   instead return `0` — refuted (894 counterexamples).
/// * **single-precision division**: reciprocal-multiply and full-`f64` evaluation
///   both differ from the oracle in the 6th significant digit.
///
/// Storage width for `s` is likewise unobservable: the operands are `f32`, so a
/// `double` field would receive the exact same correctly-rounded `f32` quotient.
#[inline]
pub fn hsv_s(r: f32, g: f32, b: f32) -> f32 {
    let max = max3(r, g, b);
    let min = min3(r, g, b);
    let delta = max - min;
    if max == 0.0 { 0.0 } else { delta / max }
}

/// Both `s` and `v` from a single reduction, matching the C++ control flow.
///
/// `hsv.h` is identical to `hsl.h` over the whole corpus (144 254 triples,
/// including 3 248 NaN-bearing and 6 500 inf-bearing rows, with `-0`/`0` and
/// `nan`/`-nan` printed distinctly) — 0 differences. Hue is therefore a single
/// shared expression and is deliberately not duplicated here.
#[inline]
pub fn rgb_to_hsv_sv(r: f32, g: f32, b: f32) -> (f32, f32) {
    let max = max3(r, g, b);
    let min = min3(r, g, b);
    let delta = max - min;
    let v = max;
    let s = if max == 0.0 { 0.0 } else { delta / max };
    (s, v)
}

#[cfg(test)]
mod hsv_sv_tests {
    use super::*;

    fn s(r: f32, g: f32, b: f32) -> f32 { hsv_s(r, g, b) }
    fn v(r: f32, g: f32, b: f32) -> f32 { hsv_v(r, g, b) }

    #[test]
    fn guard_fires_on_negative_zero_max() {
        // oracle: "0" (not "-inf"): max == -0.0 takes the `== 0` guard.
        assert_eq!(s(-0.0, -1.0, -2.0), 0.0);
        assert!(!s(-0.0, -1.0, -2.0).is_sign_negative()); // +0.0, not delta, not -0.0
        // oracle: "0" with delta == +inf.
        assert_eq!(s(-0.0, f32::NEG_INFINITY, 0.0), 0.0);
        assert!(!s(-0.0, f32::NEG_INFINITY, 0.0).is_sign_negative());
    }

    #[test]
    fn guard_is_eq_not_le() {
        // oracle: "-1"  (a `<= 0` guard would give "0")
        assert_eq!(s(-1.0, -1.0, -2.0), -1.0);
        // oracle: "-0"  (a `> 0` guard would give "+0")
        let x = s(-1.0, -1.0, -1.0);
        assert_eq!(x, 0.0);
        assert!(x.is_sign_negative());
    }

    #[test]
    fn no_epsilon_guard() {
        // oracle: "2.55212e+38"
        assert_eq!(s(1.175_494_35e-38, -3.0, -3.0), 3.0f32 / 1.175_494_35e-38f32);
    }

    #[test]
    fn nan_max_divides() {
        assert!(s(f32::NAN, 0.0, 0.0).is_nan()); // oracle: "nan"
        assert!(s(f32::INFINITY, f32::INFINITY, f32::INFINITY).is_nan()); // oracle: "-nan"
    }

    #[test]
    fn v_is_exact_max() {
        assert_eq!(v(-1.0, -1.0, -1.0), -1.0); // no clamp to 0
        assert_eq!(v(0.0, -0.5, 1.0e-7), 1.0e-7f32); // not min + delta
        assert_eq!(v(0.0, 1.0, f32::NEG_INFINITY), 1.0);
        assert!(v(-0.0, 0.0, 0.0).is_sign_negative()); // -0 preserved
    }

    #[test]
    fn regressions() {
        assert_eq!(s(0.4, 0.2, 0.8), 0.75);
        assert_eq!(v(0.4, 0.2, 0.8), 0.8);
        assert_eq!(s(0.0, -0.5, 0.0), 0.0);
        assert_eq!(s(-1.0, -2.0, -3.0), -2.0);
    }
}

//! Exact reimplementation of `std::cout << (float)v` with default stream flags,
//! which libstdc++ implements as `printf("%.6g", (double)v)` in the classic locale.
//!
//! Every step is exact: the binary32 value is expanded as an exact rational
//! `num / den` and rounded to 6 significant decimal digits with round-half-to-even
//! on the *exact* value (glibc rounds the infinitely precise decimal expansion of
//! the argument under the FE_TONEAREST rounding mode). No f64 arithmetic is used
//! for rounding, so all 2^32 f32 patterns are correct.
//!
//! VERIFIED: all 2^32 = 4,294,967,296 f32 bit patterns compared byte-for-byte
//! against a C++ oracle (`std::cout << bitcast<float>(pattern)`) built with
//! g++ 12.1.0 -O2. 0 mismatches.
//!
//! Discriminating inputs that pin the behaviour down:
//!
//! | input (f32 bits) | value          | output        | what it proves                     |
//! |------------------|----------------|---------------|------------------------------------|
//! | 0x4996b428       | 1234565        | `1.23456e+06` | exact tie -> half-to-EVEN (down)   |
//! | 0x4996b478       | 1234575        | `1.23458e+06` | exact tie -> half-to-EVEN (up)     |
//! | 0x49742450       | 1000005        | `1e+06`       | tie down, then trailing-zero strip |
//! | 0x497424f0       | 1000015        | `1.00002e+06` | tie up                             |
//! | 0x497423f8       | 999999.5       | `1e+06`       | exponent taken AFTER rounding      |
//! | 0x38d1b716       | 9.99999975e-05 | `0.0001`      | rounds up to 1e-4 => X=-4 => FIXED |
//! | 0x3727c5ac       | 1e-05          | `1e-05`       | X=-5 => scientific                 |
//! | 0x38d1b717       | 1e-04          | `0.0001`      | X=-4 => fixed                      |
//! | 0x47c35000       | 100000         | `100000`      | X=5  => fixed                      |
//! | 0x49742400       | 1000000        | `1e+06`       | X=6  => scientific                 |
//! | 0x00000001       | 1.4013e-45     | `1.4013e-45`  | 3-digit exponent, subnormal        |
//! | 0x7f7fffff       | 3.40282e+38    | `3.40282e+38` | 2-digit exponent, max normal       |
//! | 0xffc00000       | -NaN           | `-nan`        | sign bit of NaN is printed         |
//! | 0x80000000       | -0.0           | `-0`          | negative zero                      |

use std::cmp::Ordering;

// ---------------------------------------------------------------------------
// Minimal big unsigned integer (little-endian u32 limbs, normalised: no
// trailing zero limbs; the empty vector represents 0).
// ---------------------------------------------------------------------------

#[derive(Clone, Debug)]
struct Big {
    d: Vec<u32>,
}

impl Big {
    fn from_u64(mut v: u64) -> Big {
        let mut d = Vec::with_capacity(6);
        while v != 0 {
            d.push((v & 0xffff_ffff) as u32);
            v >>= 32;
        }
        Big { d }
    }

    fn is_zero(&self) -> bool {
        self.d.is_empty()
    }

    fn trim(&mut self) {
        while let Some(&0) = self.d.last() {
            self.d.pop();
        }
    }

    fn cmp_big(&self, other: &Big) -> Ordering {
        if self.d.len() != other.d.len() {
            return self.d.len().cmp(&other.d.len());
        }
        for i in (0..self.d.len()).rev() {
            if self.d[i] != other.d[i] {
                return self.d[i].cmp(&other.d[i]);
            }
        }
        Ordering::Equal
    }

    fn mul_u32(&mut self, m: u32) {
        if m == 0 {
            self.d.clear();
            return;
        }
        let mut carry: u64 = 0;
        for limb in self.d.iter_mut() {
            let t = (*limb as u64) * (m as u64) + carry;
            *limb = (t & 0xffff_ffff) as u32;
            carry = t >> 32;
        }
        while carry != 0 {
            self.d.push((carry & 0xffff_ffff) as u32);
            carry >>= 32;
        }
    }

    fn mul_pow10(&mut self, mut e: u32) {
        if self.is_zero() {
            return;
        }
        while e >= 9 {
            self.mul_u32(1_000_000_000);
            e -= 9;
        }
        if e > 0 {
            const P: [u32; 9] = [
                1, 10, 100, 1000, 10_000, 100_000, 1_000_000, 10_000_000, 100_000_000,
            ];
            self.mul_u32(P[e as usize]);
        }
    }

    /// self <<= n  (n in bits)
    fn shl_bits(&mut self, n: usize) {
        if self.is_zero() || n == 0 {
            return;
        }
        let limbs = n / 32;
        let bits = n % 32;
        if bits > 0 {
            let mut carry: u32 = 0;
            for limb in self.d.iter_mut() {
                let nv = (*limb << bits) | carry;
                carry = *limb >> (32 - bits);
                *limb = nv;
            }
            if carry != 0 {
                self.d.push(carry);
            }
        }
        if limbs > 0 {
            let mut nd = vec![0u32; limbs];
            nd.extend_from_slice(&self.d);
            self.d = nd;
        }
    }

    fn shl(&self, n: usize) -> Big {
        let mut c = self.clone();
        c.shl_bits(n);
        c
    }

    /// self -= other  (requires self >= other)
    fn sub_assign(&mut self, other: &Big) {
        let mut borrow: i64 = 0;
        for i in 0..self.d.len() {
            let o = if i < other.d.len() { other.d[i] as i64 } else { 0 };
            let mut t = self.d[i] as i64 - o - borrow;
            if t < 0 {
                t += 1i64 << 32;
                borrow = 1;
            } else {
                borrow = 0;
            }
            self.d[i] = t as u32;
        }
        debug_assert_eq!(borrow, 0);
        self.trim();
    }

    fn pow2(e: usize) -> Big {
        Big::from_u64(1).shl(e)
    }
}

